/** State snapshots and financial reports. All personal work stays in this browser. */
export function createExpansion(ctx) {
  const {e,num,money,icon,btn,external,heading,openModal,download,buildCSV,toast}=ctx;
  let financeFilters={},financeVisible=30,regionQuery='',financeSelected=[];
  const D=()=>ctx.data(),S=()=>ctx.state();
  const unique=values=>[...new Set(values.filter(v=>v!=null&&v!==''))].sort();
  const text=v=>typeof v==='object'?JSON.stringify(v):String(v??'');
  const select=(name,label,values,value='')=>`<label class="filter-field"><span>${e(label)}</span><select name="${name}"><option value="">All</option>${values.map(v=>`<option ${String(v)===String(value)?'selected':''} value="${e(v)}">${e(v)}</option>`).join('')}</select></label>`;
  const stateInfo=()=>D().stateCatalog?.find(s=>s.id===S().dataset);
  function datasetPicker(){return `<label class="dataset-picker"><span>Counselling dataset</span><select id="counselling-dataset"><option value="mcc" ${S().dataset==='mcc'?'selected':''}>MCC · All India</option>${(D().stateCatalog||[]).filter(s=>s.recordCount).map(s=>`<option value="${e(s.id)}" ${S().dataset===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></label>`}
  function banner(){const x=D().expansion||{};return `<section class="expansion-banner section-gap"><div><span class="hero-kicker">ALL INDIA + STATE COUNSELLING</span><h2>Your research, across India.</h2><p>${num(x.stateRecords)} state seat and cutoff records. ${num(x.financialReports)} fee, stipend and bond reports. Each keeps its authority and source year.</p><p class="small text-muted">${num(x.jurisdictionsWithRecords)} of ${num(x.jurisdictions)} jurisdictions have numerical seat or cutoff datasets. Remaining gaps are listed openly.</p></div><div class="hero-actions"><a href="#states" class="btn primary">Find my state ${icon('arrow')}</a><a href="#fees" class="btn secondary">Explore fees & bonds</a></div></section>`}
  async function loadState(id,activate=true,path){
    const s=D().stateCatalog?.find(x=>x.id===id);
    if(id!=='mcc'&&!s)return;
    if(s&&!D().loadedStates.has(id)){
      toast(`Loading ${s.name} official snapshots…`);
      const chunks=await Promise.all(s.recordFiles.map(async file=>{const r=await fetch('./'+file);if(!r.ok)throw new Error('State dataset could not be loaded.');return r.json()}));
      D().records.push(...chunks.flat());D().loadedStates.add(id);ctx.refreshCatalog();
    }
    if(activate){S().dataset=id;S().filters=s?.rankTypes?.length===1?{rankType:s.rankTypes[0]}:{};S().visible=36;S().loadedDatasets=[...D().loadedStates];ctx.save();if(path)ctx.navigate(path);else ctx.render()}
  }
  function states(){const list=D().stateCatalog||[],q=regionQuery.toLowerCase();return heading('Counselling, state by state.','Find your authority, published snapshots and financial reports. Source years are shown separately.',`<span class="chip">${list.length} states & union territories</span>`)+`<form id="state-search" class="panel filters"><label class="filter-field search-field"><span>Find your state or union territory</span><input name="search" value="${e(regionQuery)}" placeholder="Search a state or authority"></label><button class="btn primary">Find state</button></form><div class="data-note">Numerical datasets are partial snapshots. A portal link alone does not mean its seats, cutoffs or financial terms have been imported. State merit rank and NEET PG AIR are different scales.</div><div class="state-grid">${list.filter(s=>(s.name+' '+s.authority).toLowerCase().includes(q)).map(s=>`<article class="panel state-card"><div class="state-card-title"><span class="stat-icon">${icon('pin')}</span><span class="badge ${s.recordCount?'success':'neutral'}">${s.recordCount?'Numerical snapshot':'Source directory'}</span></div><h2>${e(s.name)}</h2><p class="small text-muted">${e(s.authority)}</p><div class="state-counts"><div><strong>${num(s.seatRecords)}</strong><span>seat pools</span></div><div><strong>${num(s.cutoffRecords)}</strong><span>cutoff pools</span></div><div><strong>${num(s.financialRecords)}</strong><span>financial reports</span></div></div><p class="small">${s.years.length?'Record years: '+e(s.years.join(', ')):'No numerical seat or cutoff snapshot imported'}${s.rankTypes.length?'<br>Rank scale: '+e(s.rankTypes.join(' · ')):''}</p><p class="coverage-note">${e(s.coverageNote||s.status||'Partial source coverage.')}</p><div class="toolbar">${s.seatRecords?btn('Seats','state-seats','secondary',`data-id="${e(s.id)}"`):''}${s.cutoffRecords?btn('Cutoffs','state-cutoffs','secondary',`data-id="${e(s.id)}"`):''}${s.financialRecords?btn('Fees & bonds','state-finance','subtle',`data-id="${e(s.name)}"`):''}</div><details class="state-docs"><summary>Official sources & snapshot details</summary><p>${external(s.authorityUrl,'Counselling authority')}</p>${(s.seatSnapshots||[]).map(x=>`<p class="small"><strong>${num(x.seats)} seats</strong> · ${e(x.year)} · ${e(x.round)}<br>${e(x.counselling)}</p>`).join('')}${(s.documents||[]).map(x=>`<p class="small">${external(x.url,x.title)} <span class="text-muted">${e(x.year||'')}</span></p>`).join('')}<p class="small text-muted">Checked ${e(s.checkedAt)}</p></details></article>`).join('')}</div>`}
  async function loadFinance(){if(D().financeLoaded)return;if(D().financeLoading)return D().financeLoading;D().financeLoading=(async()=>{const chunks=await Promise.all((D().financialRecordFiles||[]).map(async file=>{const r=await fetch('./'+file);if(!r.ok)throw new Error('Financial reports could not be loaded.');return r.json()}));D().financials=chunks.flat();D().financeLoaded=true;})();try{await D().financeLoading}finally{D().financeLoading=null}}
  function matchedFinance(){const q=(financeFilters.search||'').toLowerCase();return (D().financials||[]).filter(f=>(!q||[f.instituteName,f.title,f.course,f.scope,f.state].map(text).join(' ').toLowerCase().includes(q))&&(!financeFilters.state||f.state===financeFilters.state)&&(!financeFilters.year||String(f.year)===financeFilters.year)&&(!financeFilters.field||f[financeFilters.field]!=null||(financeFilters.field==='monthlyStipend'&&f.stipendByYear?.some(v=>v!=null))))}
  const stipend=f=>f.stipendByYear?.some(v=>v!=null)?f.stipendByYear.map((v,i)=>`Y${i+1}: ${money(v)}`).join(' · '):money(f.monthlyStipend);
  function financeCard(f){return `<article class="financial-card"><div class="toolbar"><span class="badge neutral">${e(f.state)} · ${e(f.year??'Year not stated')}</span><button class="btn subtle" data-action="finance-compare" data-id="${e(f.id)}">${financeSelected.includes(f.id)?'Selected':'Compare'}</button></div><h3><button data-action="finance-detail" data-id="${e(f.id)}">${e(f.instituteName||f.title)}</button></h3><p class="small text-muted">${e(f.course||f.program||f.title)}${f.quota?' · '+e(f.quota):''}</p><p class="small">${e(text(f.scope||f.feeScope))}</p><dl class="finance-metrics"><div><dt>Annual course fee</dt><dd>${money(f.annualFee)}</dd></div><div><dt>Monthly PG stipend</dt><dd>${e(stipend(f))}</dd></div><div><dt>Service obligation</dt><dd>${f.bondYears==null?'Not reported':num(f.bondYears)+' years'}</dd></div><div><dt>Service bond penalty</dt><dd>${money(f.bondPenalty)}</dd></div></dl>${f.discontinuationPenalty!=null?`<p class="small">Course discontinuation: <strong>${money(f.discontinuationPenalty)}</strong> · see conditions</p>`:''}<details><summary>Conditions & fee breakdown</summary><p class="small financial-notes">${e(text(f.notes))}</p>${f.rawCollegeStipend?`<p class="small"><strong>Institution disclosure:</strong> ${e(f.rawCollegeStipend)}</p><p class="small text-muted">Received by NMC: ${e(f.reportReceived||'date not stated')}. Compilation published ${e(f.publicationYear)}.</p>`:''}${f.feePerTerm!=null?`<p>Per-term fee: ${money(f.feePerTerm)} (${e(f.feeReferenceYear||f.year)})</p>`:''}</details><div class="financial-card-footer">${external(f.sourceUrl,'Official source')}${btn('Full report','finance-detail','subtle',`data-id="${e(f.id)}"`)}</div></article>`}
  function costForm(){return `<section class="panel section-gap"><div class="panel-header"><h2>Plan your course budget</h2><span class="small text-muted">Your own figures, calculated on this device</span></div><form id="cost-form" class="panel-body form-grid">${[['tuition','Annual course fee (₹)',''],['years','Years of study','3'],['living','Monthly living costs (₹)','10000'],['stipend','Monthly stipend (₹)','0']].map(([name,label,value])=>`<label class="field"><span>${label}</span><input type="number" min="${name==='years'?'0.5':'0'}" step="${name==='years'?'0.5':'1'}" name="${name}" value="${value}" required></label>`).join('')}<button class="btn primary">Calculate budget</button><div id="cost-result" aria-live="polite"></div></form></section>`}
  function fees(){if(!D().financeLoaded){if(!D().financeError)loadFinance().then(()=>{if(location.hash==='#fees')ctx.render()}).catch(err=>{D().financeError=err.message;ctx.render()});return heading('Fees, stipends & bonds.','Institution and policy reports, with their source year and conditions.')+`<div class="panel panel-body">${e(D().financeError||'Loading official financial reports…')}</div>`}const rows=matchedFinance(),all=D().financials;return heading('Know the cost. Read the conditions.','Search institution and policy reports. Fees, PG stipends and service bonds retain their original scope.',btn(icon('download')+' Export matches','finance-export'))+`<div class="data-note">Published figures cover specific years, courses and quotas. “Not reported” means unknown, not zero. Annual course fees may include university charges; open the conditions for the breakdown. A disclosure is not proof of actual stipend payment.</div><form id="finance-filters" class="panel filters"><div class="toolbar"><label class="filter-field search-field"><span>Institution, specialty or policy</span><input name="search" value="${e(financeFilters.search||'')}" placeholder="Search financial reports"></label>${select('state','State',unique(all.map(f=>f.state)),financeFilters.state)}${select('year','Source year',unique(all.map(f=>f.year)).reverse(),financeFilters.year)}<label class="filter-field"><span>Reported field</span><select name="field"><option value="">All reports</option>${[['annualFee','Annual fee'],['monthlyStipend','PG stipend'],['bondYears','Service obligation'],['bondPenalty','Service bond penalty'],['discontinuationPenalty','Discontinuation penalty']].map(([v,l])=>`<option value="${v}" ${financeFilters.field===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn primary">Apply filters</button>${btn('Reset','finance-reset','subtle')}</div></form><div class="toolbar results-bar"><p><strong>${num(rows.length)}</strong> matching reports · ${unique(rows.map(f=>f.state)).length} states / territories</p>${financeSelected.length?btn(`Compare ${financeSelected.length} reports`,'finance-comparison','primary'):''}</div><div class="financial-grid">${rows.slice(0,financeVisible).map(financeCard).join('')}</div>${!rows.length?'<div class="empty-state"><h3>No matching financial report</h3><p>Try a broader search or open your state’s official sources.</p></div>':''}${rows.length>financeVisible?`<div class="toolbar section-gap">${btn('Show more reports','finance-more')}<span class="small">Showing ${financeVisible} of ${num(rows.length)}. Export includes every match.</span></div>`:''}${D().dnbAnnualFeeReference?`<section class="panel section-gap"><div class="panel-body"><h2>DNB fee policy</h2><p>The ${e(D().dnbAnnualFeeReference.year)} NBEMS policy lists total annual fee heads of ${money(D().dnbAnnualFeeReference.totalOfListedHeads)}. ${e(D().dnbAnnualFeeReference.notes)}</p>${external(D().dnbAnnualFeeReference.sourceUrl,'Read the NBEMS policy')}</div></section>`:''}${costForm()}`}
  function financeDetail(id){const f=D().financials.find(f=>f.id===id);if(!f)return;openModal(f.instituteName||f.title,financeCard(f)+`<p class="small text-muted">Source year ${e(f.year??'Year not stated')} · page ${e(f.sourcePage||'see publication')} · checked ${e(f.checkedAt)}. Conditions: ${e(text(f.notes))}</p>`)}
  function compareFinance(){const rows=D().financials.filter(f=>financeSelected.includes(f.id));const metrics=[['State',f=>f.state],['Year',f=>f.year],['Course / programme',f=>f.course||f.program||'See scope'],['Scope',f=>text(f.scope||f.feeScope)],['Annual course fee',f=>money(f.annualFee)],['Monthly PG stipend',stipend],['Service obligation',f=>f.bondYears==null?'Not reported':f.bondYears+' years'],['Service bond penalty',f=>money(f.bondPenalty)],['Discontinuation penalty',f=>money(f.discontinuationPenalty)],['Conditions',f=>text(f.notes)]];openModal('Financial reports, side by side',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Field</th>${rows.map(f=>`<th>${e(f.instituteName||f.title)}</th>`).join('')}</tr></thead><tbody>${metrics.map(([k,get])=>`<tr><th>${k}</th>${rows.map(f=>`<td>${e(get(f))}</td>`).join('')}</tr>`).join('')}<tr><th>Publication</th>${rows.map(f=>`<td>${external(f.sourceUrl,'Official source')}</td>`).join('')}</tr></tbody></table></div>`)}
  function coverage(){const x=D().expansion||{};return `<section class="panel section-gap"><div class="panel-header"><h2>Nationwide coverage, measured honestly</h2><span class="badge neutral">${e(x.checkedAt)}</span></div><div class="panel-body"><p>${num(x.jurisdictions)} jurisdiction directories; ${num(x.jurisdictionsWithRecords)} contain imported numerical state records. ${num(x.stateRecords)} state records are separate from the MCC dataset. ${num(x.financialReports)} financial reports cover ${num(x.financialStates)} states and territories.</p><p>Coverage is partial. Missing reports and older snapshots are identified under each state. There is no claim that every institution, round or financial field has been captured.</p><a href="#states" class="btn secondary">Inspect state coverage</a><h3 class="section-gap">Free tools available now</h3><p>Institution and specialty explorer, source-based cutoff and seat filters, financial search and comparisons, rank comparison, unlimited choice lists, CSV export, printing, a budget calculator, official-source guidance, personal reminders and local backups.</p><p class="small text-muted">Source updates are curated releases, not a live feed. We do not supply human counselling, a community service, live AI advice, private candidate histories or automatic submission to counselling authorities. Zyjock is independent and is not affiliated with Zynerd.</p></div></section>`}
  async function action(a,id){if(a==='state-seats'||a==='state-cutoffs'){await loadState(id,true,a==='state-seats'?'seats':'cutoffs');return true}if(a==='state-finance'){financeFilters={state:id};financeVisible=30;ctx.navigate('fees');return true}if(a==='finance-reset'){financeFilters={};financeVisible=30;ctx.render();return true}if(a==='finance-more'){financeVisible+=30;ctx.render();return true}if(a==='finance-detail'){financeDetail(id);return true}if(a==='finance-export'){download(buildCSV(matchedFinance().map(f=>({...f,stipendByYear:JSON.stringify(f.stipendByYear||[])})),['instituteName','state','course','quota','year','scope','annualFee','monthlyStipend','stipendByYear','bondYears','bondPenalty','discontinuationPenalty','notes','sourcePage','sourceUrl']),'zyjock-financial-reports.csv','text/csv');return true}if(a==='finance-compare'){if(financeSelected.includes(id))financeSelected=financeSelected.filter(x=>x!==id);else if(financeSelected.length<3)financeSelected.push(id);else toast('Compare up to three reports at a time.','warning');ctx.render();return true}if(a==='finance-comparison'){compareFinance();return true}return false}
  function submit(id,values){if(id==='finance-filters'){financeFilters=values;financeVisible=30;ctx.render();return true}if(id==='state-search'){regionQuery=values.search;ctx.render();return true}return false}
  return {states,fees,banner,coverage,datasetPicker,stateInfo,loadState,loadFinance,action,submit};
}
